  (UNHEX(REPLACE('00000000-0000-4000-b003-000000000047', '-', '')), UNHEX(REPLACE('00000000-0000-4000-b001-000000000047', '-', '')), 'Tăng Thị Nhung', 'Thợ điện lạnh 2 năm, bơm gas, sửa chữa máy lạnh công suất lớn cho quán ăn, cửa hàng. Nhận thanh toán chuyển khoản hoặc tiền mặt đều được, có xuất hoá đơn nếu cần.', 'Sóc Trăng', 9.6340000, 106.0050000, 25, 'VERIFIED', NOW(3), NOW(3)),
  (UNHEX(REPLACE('00000000-0000-4000-b003-000000000048', '-', '')), UNHEX(REPLACE('00000000-0000-4000-b001-000000000048', '-', '')), 'Kiều Gia Huy', 'Thợ điện công nghiệp quy mô nhỏ, 9 năm kinh nghiệm tủ điện, động cơ, hệ thống 3 pha. Rất quen đường trong khu vực nên tới nhanh, không để khách chờ lâu.', 'Sóc Trăng', 9.6460000, 106.0200000, 10, 'VERIFIED', NOW(3), NOW(3)),
  (UNHEX(REPLACE('00000000-0000-4000-b003-000000000049', '-', '')), UNHEX(REPLACE('00000000-0000-4000-b001-000000000049', '-', '')), 'Dương Trung Kiên', 'Chuyên xử lý rò rỉ, lắp đặt đường ống cấp thoát nước, 5 năm trong nghề.', 'Hà Giang', 22.8580000, 104.9300000, 15, 'VERIFIED', NOW(3), NOW(3)),
  (UNHEX(REPLACE('00000000-0000-4000-b003-000000000050', '-', '')), UNHEX(REPLACE('00000000-0000-4000-b001-000000000050', '-', '')), 'Vũ Hồng Phong', 'Chuyên lắp máy lọc nước RO, bảo trì định kỳ, 1 năm trong nghề, giá rõ ràng. Ưu tiên làm kỹ, không làm ẩu cho xong việc, dù mất thêm thời gian.', 'Hà Giang', 22.7500000, 104.9450000, 20, 'VERIFIED', NOW(3), NOW(3)),
  (UNHEX(REPLACE('00000000-0000-4000-b003-000000000051', '-', '')), UNHEX(REPLACE('00000000-0000-4000-b001-000000000051', '-', '')), 'Kiều Xuân Bách', 'Thợ điện dân dụng 8 năm kinh nghiệm, chuyên sửa ổ cắm, công tắc, đường dây âm tường. Ưu tiên làm kỹ, không làm ẩu cho xong việc, dù mất thêm thời gian.', 'Hà Giang', 22.7620000, 104.9600000, 25, 'VERIFYING', NOW(3), NOW(3)),
  (UNHEX(REPLACE('00000000-0000-4000-b003-000000000052', '-', '')), UNHEX(REPLACE('00000000-0000-4000-b001-000000000052', '-', '')), 'Đinh Thị Phượng', 'Chuyên vệ sinh bảo trì máy lạnh định kỳ, 4 năm trong nghề, giá hợp lý.', 'Cao Bằng', 22.6440000, 106.2650000, 10, 'NOT_SUBMITTED', NOW(3), NOW(3)),
  (UNHEX(REPLACE('00000000-0000-4000-b003-000000000053', '-', '')), UNHEX(REPLACE('00000000-0000-4000-b001-000000000053', '-', '')), 'Mai Minh Đức', 'Thợ điện công nghiệp nhỏ, 0 năm, xử lý sự cố mất pha, nhảy aptomat tổng gấp. Được nhiều khách quen giới thiệu lại, làm việc có tâm.', 'Cao Bằng', 22.6560000, 106.2800000, 15, 'REJECTED', NOW(3), NOW(3)),
  (UNHEX(REPLACE('00000000-0000-4000-b003-000000000054', '-', '')), UNHEX(REPLACE('00000000-0000-4000-b001-000000000054', '-', '')), 'Đỗ Thị Kim', 'Thợ cấp thoát nước 7 năm kinh nghiệm, thông tắc, sửa ống nước, chống thấm. Có bảo hành 1 tháng cho mọi việc đã làm, sai đâu sửa lại miễn phí.', 'Cao Bằng', 22.6680000, 106.2950000, 20, 'CANCELLED', NOW(3), NOW(3)),
  (UNHEX(REPLACE('00000000-0000-4000-b003-000000000055', '-', '')), UNHEX(REPLACE('00000000-0000-4000-b001-000000000055', '-', '')), 'Lý Đăng Khoa', 'Thợ lắp đặt và bảo trì thiết bị nước 3 năm: máy lọc nước, vòi sen, máy bơm.', 'Bạc Liêu', 9.3100000, 105.7700000, 25, 'VERIFIED', NOW(3), NOW(3)),
  (UNHEX(REPLACE('00000000-0000-4000-b003-000000000056', '-', '')), UNHEX(REPLACE('00000000-0000-4000-b001-000000000056', '-', '')), 'Kiều Trung Kiên', 'Thợ điện dân dụng, 10 năm kinh nghiệm, xử lý sự cố chập cháy, aptomat nhảy liên tục. Tự mang đầy đủ dụng cụ, đồ nghề, khách không cần chuẩn bị gì thêm.', 'Bạc Liêu', 9.3220000, 105.6800000, 10, 'VERIFIED', NOW(3), NOW(3)),
  (UNHEX(REPLACE('00000000-0000-4000-b003-000000000057', '-', '')), UNHEX(REPLACE('00000000-0000-4000-b001-000000000057', '-', '')), 'Lương Thị Mai', 'Thợ điện lạnh 6 năm kinh nghiệm: sửa máy lạnh, tủ lạnh, tủ đông các loại. Tự mang đầy đủ dụng cụ, đồ nghề, khách không cần chuẩn bị gì thêm.', 'Bạc Liêu', 9.3340000, 105.6950000, 15, 'VERIFIED', NOW(3), NOW(3)),
  (UNHEX(REPLACE('00000000-0000-4000-b003-000000000058', '-', '')), UNHEX(REPLACE('00000000-0000-4000-b001-000000000058', '-', '')), 'Lâm Trọng Nhân', 'Chuyên bảo trì tủ điện tổng cho xưởng nhỏ, cửa hàng, 2 năm kinh nghiệm.', 'Kon Tum', 14.4160000, 108.0100000, 20, 'VERIFIED', NOW(3), NOW(3)),
  (UNHEX(REPLACE('00000000-0000-4000-b003-000000000059', '-', '')), UNHEX(REPLACE('00000000-0000-4000-b001-000000000059', '-', '')), 'Dương Thị Ngọc', 'Thợ cấp thoát nước 9 năm, nhận việc thông cống, sửa bồn cầu gấp trong ngày. Báo giá rõ ràng trước khi làm, không phát sinh thêm phí ngoài dự kiến.', 'Kon Tum', 14.4280000, 108.0250000, 25, 'VERIFYING', NOW(3), NOW(3)),
  (UNHEX(REPLACE('00000000-0000-4000-b003-000000000060', '-', '')), UNHEX(REPLACE('00000000-0000-4000-b001-000000000060', '-', '')), 'Phạm Thành Long', 'Chuyên lắp đặt máy nước nóng, bình nóng lạnh, 5 năm kinh nghiệm. Có thể nhận việc gấp trong ngày nếu khách cần xử lý sớm.', 'Kon Tum', 14.3200000, 108.0400000, 10, 'NOT_SUBMITTED', NOW(3), NOW(3));
